-- Initial warehouse schema. Applied to connected Supabase project.
create extension if not exists pgcrypto;
create table if not exists public.dataset_sources(id uuid primary key default gen_random_uuid(),source_name text not null,publisher text not null,source_url text not null unique,dataset_description text,geography text,refresh_frequency text,license_name text,last_checked_at timestamptz,last_loaded_at timestamptz,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.dim_date(date_key integer primary key,full_date date not null unique,year smallint not null,quarter smallint not null check(quarter between 1 and 4),month smallint not null check(month between 1 and 12),month_name text not null,week_of_year smallint not null,day_of_month smallint not null,day_of_week smallint not null,is_weekend boolean not null);
create table if not exists public.dim_location(id uuid primary key default gen_random_uuid(),country_code text,country_name text not null,admin1_code text,admin1_name text,admin2_code text,admin2_name text,location_label text not null,created_at timestamptz not null default now(),unique nulls not distinct(country_name,admin1_name,admin2_name,location_label));
create table if not exists public.dim_disease(id uuid primary key default gen_random_uuid(),disease_code text,disease_name text not null,disease_category text,icd_code text,created_at timestamptz not null default now(),unique nulls not distinct(disease_code,disease_name,disease_category,icd_code));
create table if not exists public.fact_disease_cases(id bigint generated always as identity primary key,date_key integer not null references public.dim_date(date_key),location_id uuid not null references public.dim_location(id),disease_id uuid not null references public.dim_disease(id),source_id uuid references public.dataset_sources(id),case_count numeric(16,2) not null check(case_count>=0),measure_unit text not null default 'cases',is_estimated boolean not null default false,source_record_id text,loaded_at timestamptz not null default now(),unique(date_key,location_id,disease_id,source_id,source_record_id));
create table if not exists public.fact_hospital_admissions(id bigint generated always as identity primary key,date_key integer not null references public.dim_date(date_key),location_id uuid not null references public.dim_location(id),disease_id uuid references public.dim_disease(id),source_id uuid references public.dataset_sources(id),admission_count numeric(16,2) not null check(admission_count>=0),measure_unit text not null default 'admissions',is_estimated boolean not null default false,source_record_id text,loaded_at timestamptz not null default now(),unique(date_key,location_id,disease_id,source_id,source_record_id));
create table if not exists public.etl_logs(id uuid primary key default gen_random_uuid(),source_id uuid references public.dataset_sources(id),pipeline_name text not null,status text not null check(status in('started','succeeded','failed','partial')),records_read bigint not null default 0,records_inserted bigint not null default 0,records_rejected bigint not null default 0,started_at timestamptz not null default now(),finished_at timestamptz,message text,metadata jsonb not null default '{}'::jsonb);
create table if not exists public.model_runs(id uuid primary key default gen_random_uuid(),target_name text not null check(target_name in('disease_cases','hospital_admissions')),disease_id uuid references public.dim_disease(id),location_id uuid references public.dim_location(id),model_name text not null,model_family text not null check(model_family in('machine_learning','time_series')),training_start date not null,training_end date not null,test_start date not null,test_end date not null,horizon_days integer not null check(horizon_days>0),mae numeric(18,6),rmse numeric(18,6),mape numeric(18,6),status text not null default 'completed' check(status in('queued','running','completed','failed')),parameters jsonb not null default '{}'::jsonb,metrics_details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),check(training_start<=training_end),check(test_start<=test_end));
create table if not exists public.forecast_results(id bigint generated always as identity primary key,model_run_id uuid not null references public.model_runs(id) on delete cascade,forecast_date date not null,target_name text not null check(target_name in('disease_cases','hospital_admissions')),predicted_value numeric(18,4) not null check(predicted_value>=0),lower_bound numeric(18,4),upper_bound numeric(18,4),actual_value numeric(18,4),created_at timestamptz not null default now(),unique(model_run_id,forecast_date,target_name),check(lower_bound is null or lower_bound<=predicted_value),check(upper_bound is null or upper_bound>=predicted_value));
create index if not exists idx_cases_date_location on public.fact_disease_cases(date_key,location_id); create index if not exists idx_cases_disease_date on public.fact_disease_cases(disease_id,date_key); create index if not exists idx_admissions_date_location on public.fact_hospital_admissions(date_key,location_id); create index if not exists idx_forecast_date on public.forecast_results(forecast_date);
alter table public.dataset_sources enable row level security; alter table public.dim_date enable row level security; alter table public.dim_location enable row level security; alter table public.dim_disease enable row level security; alter table public.fact_disease_cases enable row level security; alter table public.fact_hospital_admissions enable row level security; alter table public.etl_logs enable row level security; alter table public.model_runs enable row level security; alter table public.forecast_results enable row level security;
create policy "Public read dataset sources" on public.dataset_sources for select to anon,authenticated using(true); create policy "Public read date dimension" on public.dim_date for select to anon,authenticated using(true); create policy "Public read location dimension" on public.dim_location for select to anon,authenticated using(true); create policy "Public read disease dimension" on public.dim_disease for select to anon,authenticated using(true); create policy "Public read disease cases" on public.fact_disease_cases for select to anon,authenticated using(true); create policy "Public read hospital admissions" on public.fact_hospital_admissions for select to anon,authenticated using(true); create policy "Public read model runs" on public.model_runs for select to anon,authenticated using(true); create policy "Public read forecasts" on public.forecast_results for select to anon,authenticated using(true);
grant select on public.dataset_sources,public.dim_date,public.dim_location,public.dim_disease,public.fact_disease_cases,public.fact_hospital_admissions,public.model_runs,public.forecast_results to anon,authenticated; grant all on public.dataset_sources,public.dim_date,public.dim_location,public.dim_disease,public.fact_disease_cases,public.fact_hospital_admissions,public.etl_logs,public.model_runs,public.forecast_results to service_role; grant usage,select on all sequences in schema public to service_role;